{{ if .Users }}
<p>Users selected.</p>
{{ else }}
<p>No users selected.</p>
{{ end }}

{{ with propertyValue $citizen.Properties "user.blood_type" }}
<p>Blood type: {{ .GetStringValue }}</p>
{{ else }}
<p>Blood type: not recorded</p>
{{ end }}

{{- if .Users -}}
<p>
Citizen: {{ $citizen.GetFirstname }} {{ $citizen.GetLastname }}<br>
DOB: {{ $citizen.GetDateofbirth }}
</p>
{{- else -}}
<p>No citizen selected.</p>
{{- end -}}

{{ if not .Vehicles }}
<p>No vehicles involved.</p>
{{ else }}
<ul>
{{- range .Vehicles -}}
<li>{{ .GetPlate }} - {{ .Owner.GetFirstname }} {{ .Owner.GetLastname }}</li>
{{- end -}}
</ul>
{{ end }}

{{ if not .Vehicles }}
<p>
No Vehicles involved.
</p>
{{ else }}
<ul>
{{- range .Vehicles -}}
<li>{{ .GetPlate }} - {{ .Owner.GetFirstname }}, {{ .Owner.GetLastname }}</li>
{{- end -}}
</ul>
{{ end }}
